void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float depth = 0.3;
    float freq = 0.5;
    float offset = 2.; // should be greater than depth

    float zoom = depth*sin(iTime * freq) + offset;

    vec2 uv2 = uv*zoom;
    uv2-= ((zoom / 2.) - 0.5) ;

    if(uv2.x < 0. || uv2.y < 0. || uv2.x > 1. || uv2.y > 1.){
        fragColor = texture(iChannel0, uv);
    }else{
        uv2.x = clamp(uv2.x, 0., 1.);
        uv2.y = clamp(uv2.y, 0., 1.);
        vec4 tex2 = texture(iChannel1, uv2);
        fragColor = tex2;
    }
}
